class Solution {
  searchMatrix(matrix, target) {
    const row = matrix.length;
    const col = matrix[0].length;
    let colHigh = col - 1;
    for (let i = 0; i < row; i++) {
      const index = this.searchLowerBoundary(matrix, i, target, colHigh);
      if (matrix[i][index] === target) {
        return true;
      } else if (matrix[i][index] < target) {
        colHigh = index;
      } else if (matrix[i][index] > target) {
        // will never reach here
      }
    }
    return false;
  }
  searchLowerBoundary(matrix, rowIndex, target, colHigh) {
    const arr = matrix[rowIndex];
    let low = 0,
      high = colHigh;
    let ans = -1;
    while (low <= high) {
      const mid = Math.floor((low + high) / 2);
      if (arr[mid] === target) {
        ans = mid;
        break;
      } else if (arr[mid] < target) {
        low = mid + 1;
        ans = low;
      } else {
        high = mid - 1;
      }
    }
    return ans;
  }
}
```

